/* ------------------------------------------------------------------------
 * Sentence questions inside the adaptive session.
 *
 * The session used to be vocabulary only — recognise it, type it, hear it,
 * one word at a time — while sentences sat on their own screen behind a
 * Practise button. Words you could already recognise never got used in
 * anything, so the course taught recognition and called it Korean.
 *
 * These functions put sentence questions into the same queue the word
 * questions come from, and choose them from what this session is already
 * working on rather than from the top of the sentence list.
 *
 * Three seams join them to the rest of the app:
 *
 *   - the engine's start() builds its queue with oreumBuildMixedQueue,
 *   - generate() hands a queued sentence back as the current exercise,
 *   - the session screen renders one with OreumSentenceCard.
 *
 * Answers go through the engine's existing recordSentenceAnswer, so a
 * sentence moves the same word progress a word question would: every word
 * in it gets credit for the sentence skill, and the grammar points it uses
 * are recorded too.
 * ---------------------------------------------------------------------- */

/* One question in five is a sentence — the weight the overall progress
 * figure already gives the sentence skill — and never more than half the
 * session, however short the learner made it. */
function oreumSentenceShare(total) {
  return Math.max(0, Math.min(Math.round(total * 0.2), Math.floor(total / 2)))
}

/* A sentence earns its place when it uses the words this session already
 * picked, leans on a word or a grammar point that keeps going wrong, and
 * has not come round recently. The weights mirror selectCards: what is
 * difficult first, what is untouched next, what is comfortable last. */
function oreumSentenceScore(engine, entry, sessionWords, cardsByKorean, now) {
  const sentence = entry.sentence
  /* A sentence with a word still missing is worth less than one you can
   * read end to end. */
  let score = 1 - Math.min(1, entry.unknown.length)

  /* Averaged over the sentence, not summed: a six-word sentence is not six
   * times as useful as a three-word one, and summing would hand every
   * session the longest sentence in the book. */
  let words = 0
  for (const word of sentence.vocab) {
    if (sessionWords.has(word)) words += 3
    const progress = cardsByKorean.get(word)?.progress
    if (!progress) continue
    const wrong = progress.recallIncorrect + progress.listeningIncorrect + progress.sentenceIncorrect
    const right = progress.recallCorrect + progress.listeningCorrect + progress.sentenceCorrect
    words += Math.min(4, wrong)
    if (progress.status === 'difficult') words += 2
    /* Recognised but never used — exactly what this is here to fix. */
    if (progress.sentenceCorrect === 0) words += 1.5
    words -= Math.min(2, right / 4)
  }
  if (sentence.vocab.length > 0) score += words / sentence.vocab.length

  let grammar = 0
  for (const id of sentence.grammar) {
    const row = engine.store.grammar.find((entry) => entry.grammarId === id)
    const asked = row ? row.correct + row.incorrect : 0
    grammar += asked === 0 ? 1 : (1 - row.correct / asked) * 2
  }
  if (sentence.grammar.length > 0) score += grammar / sentence.grammar.length

  const seen = engine.store.sentences.find((row) => row.sentenceId === sentence.id)
  if (!seen) {
    score += 1.5
  } else {
    const asked = seen.correct + seen.incorrect
    if (asked > 0) score += (1 - seen.correct / asked) * 2
    score += seen.lastReviewed === null ? 1 : Math.min(2, (now - seen.lastReviewed) / (3 * 24 * 60 * 60 * 1000))
  }

  /* All else equal, the simpler sentence first. */
  return score - (sentence.level - 1) * 0.75
}

/* The sentence questions for one session, strongest candidates first. Comes
 * back empty — and the session stays words only — while no sentence is made
 * of words the learner knows, which is the same rule the Sentences screen
 * explains on its empty state. */
function oreumSessionSentences(engine, want, focus, cards) {
  if (want <= 0) return []

  /* A listening session has nothing on screen to work a missing word out
   * from, so it only asks about sentences where every word is known. */
  const listening = focus === 'listening'
  const ready = engine.sentencesReady(listening ? 0 : 1)
  if (ready.length === 0) return []

  const sessionWords = new Set(cards.map((card) => card.korean))
  const cardsByKorean = new Map()
  for (const card of engine.store.cards) {
    if (!cardsByKorean.has(card.korean)) cardsByKorean.set(card.korean, card)
  }

  const now = Date.now()
  const ranked = ready
    .map((entry) => ({ entry, score: oreumSentenceScore(engine, entry, sessionWords, cardsByKorean, now) }))
    .sort((a, b) => b.score - a.score)

  /* Hand the builder more sentences than questions wanted: not every
   * sentence can carry every question type, and it skips the ones that
   * cannot. */
  return Fc({
    sentences: ranked.slice(0, Math.max(want * 3, 6)).map((row) => row.entry.sentence),
    pool: ia,
    count: want,
    forceType: listening ? 'SENTENCE_AUDIO' : void 0,
  })
}

/* The session queue: the words selectCards chose, with sentence questions
 * spaced through them. */
function oreumBuildMixedQueue(engine, mode, count, focus) {
  const cards = engine.selectCards(mode, count)
  if (cards.length === 0) return []

  const want = oreumSentenceShare(Math.min(count, cards.length))
  const sentences = oreumSessionSentences(engine, want, focus, cards)
  if (sentences.length === 0) return cards.map((card) => ({ cardId: card.id }))

  /* The session length the learner picked stays the session length: the
   * sentences take the place of the last few words rather than adding to
   * them. */
  const words = cards.slice(0, Math.max(1, cards.length - sentences.length)).map((card) => ({ cardId: card.id }))
  const queue = words.slice()
  /* Spread them out, and never open with one — the words in a sentence
   * read better after a couple of them have just come up on their own. */
  const step = Math.max(1, Math.floor(words.length / (sentences.length + 1)))
  sentences.forEach((exercise, index) => {
    queue.splice(Math.min(queue.length, step * (index + 1) + index), 0, { sentence: exercise })
  })
  return queue
}

/* Wrong answers come back before the end, as a different question about the
 * same sentence where one can be built. */
function oreumSentenceRetry(exercise) {
  const sentence = ia.find((row) => row.id === exercise.sentenceId)
  if (sentence) {
    const others = ['SENTENCE_ORDER', 'FILL_PARTICLE', 'SENTENCE_MEANING'].filter((type) => type !== exercise.type)
    for (const type of others) {
      const built = Fc({ sentences: [sentence], pool: ia, count: 1, forceType: type })
      if (built.length > 0) return built[0]
    }
  }
  return { ...exercise, id: yo() }
}

/* Records a sentence answer against the session and against every word and
 * grammar point the sentence uses. */
async function oreumAnswerSentence(engine, exercise, correct) {
  if (correct) engine.correct += 1
  else engine.incorrect += 1

  await engine.recordSentenceAnswer(exercise.sentenceId, correct, exercise.vocab, exercise.grammar)

  let willRepeat = false
  if (!correct) {
    const at = Math.min(engine.position + 1 + zv, engine.queue.length)
    engine.queue.splice(at, 0, { sentence: oreumSentenceRetry(exercise) })
    willRepeat = true
  }

  return { correct, willRepeat, state: engine.state() }
}

function oreumSpeakSentence(engine, text) {
  const voice = engine.store.settings.voice
  Ne.speak({ text, lang: 'ko', rate: voice.koreanRate, volume: voice.volume, voiceId: voice.koreanVoiceId })
}

/* One sentence question, wearing the session's own chrome so a session
 * reads as one thing rather than two screens taking turns. The markup
 * matches the Sentences screen, which is where the styling comes from. */
function OreumSentenceCard(props) {
  const engine = props.engine
  const exercise = props.exercise
  const session = props.session
  const [placed, setPlaced] = Z.useState([])
  const [picked, setPicked] = Z.useState(null)
  const [outcome, setOutcome] = Z.useState(null)
  const [busy, setBusy] = Z.useState(false)

  Z.useEffect(() => {
    setPlaced([])
    setPicked(null)
    setOutcome(null)
    if (exercise.audioOnly) oreumSpeakSentence(engine, exercise.korean)
  }, [engine, exercise.id, exercise.audioOnly, exercise.korean])

  const answer = async (correct) => {
    if (outcome !== null || busy) return
    setBusy(true)
    try {
      const next = await oreumAnswerSentence(engine, exercise, correct)
      setOutcome(next)
      props.onState(next.state)
    } finally {
      setBusy(false)
    }
  }

  const ordering = exercise.type === 'SENTENCE_ORDER'
  const tiles = exercise.tiles ?? []
  const order = exercise.answerOrder ?? []
  const stage = [f.jsx('p', { className: 'question', children: exercise.question }, 'question')]

  if (ordering) {
    stage.push(
      f.jsx(
        'div',
        {
          className: 'slot',
          children:
            placed.length === 0
              ? f.jsx('span', { className: 'hint', style: { margin: 0 }, children: 'Tap the words in order' })
              : placed.map((word, index) =>
                  f.jsx(
                    'button',
                    {
                      className: 'word-tile placed ko',
                      disabled: outcome !== null,
                      onClick: () => setPlaced(placed.filter((_, at) => at !== index)),
                      children: word,
                    },
                    word + index
                  )
                ),
        },
        'slot'
      ),
      f.jsx('p', { className: 'hint', style: { margin: 0, textAlign: 'center' }, children: exercise.english }, 'english')
    )
  } else if (exercise.audioOnly) {
    stage.push(
      f.jsxs(
        'button',
        {
          className: 'audio-button',
          onClick: () => oreumSpeakSentence(engine, exercise.korean),
          children: [
            f.jsx('span', { className: 'audio-glyph', children: '🔊' }),
            f.jsx('span', { children: 'Play again' }),
          ],
        },
        'audio'
      )
    )
  } else {
    stage.push(
      f.jsx(
        'p',
        {
          className: 'sentence-korean ko',
          style: { textAlign: 'center' },
          onClick: () => oreumSpeakSentence(engine, exercise.korean),
          children: exercise.type === 'FILL_PARTICLE' ? exercise.masked : exercise.korean,
        },
        'korean'
      )
    )
  }

  const answers = ordering
    ? [
        f.jsx(
          'div',
          {
            className: 'tile-list',
            children: tiles.map((word, index) => {
              const used = placed.filter((entry) => entry === word).length
              const spent = used >= tiles.filter((entry) => entry === word).length
              return f.jsx(
                'button',
                {
                  className: 'word-tile ko' + (spent ? ' spent' : ''),
                  disabled: spent || outcome !== null,
                  onClick: () => setPlaced(placed.concat([word])),
                  children: word,
                },
                word + index
              )
            }),
          },
          'tiles'
        ),
        outcome === null
          ? f.jsx(
              'button',
              {
                className: 'btn primary',
                style: { marginTop: 14 },
                disabled: placed.length !== order.length || busy,
                onClick: () => answer(Vy(placed, order)),
                children: 'Check',
              },
              'check'
            )
          : null,
      ]
    : [
        f.jsx(
          'div',
          {
            className: 'choices',
            children: (exercise.choices ?? []).map((choice) => {
              let className = 'choice'
              if (outcome !== null) {
                if (choice.id === exercise.answerId) className += ' correct'
                else if (choice.id === picked) className += ' wrong'
                else className += ' dimmed'
              }
              return f.jsx(
                'button',
                {
                  className,
                  disabled: outcome !== null || busy,
                  onClick: () => {
                    setPicked(choice.id)
                    answer(choice.id === exercise.answerId)
                  },
                  children: f.jsx('span', { className: choice.hangul ? 'choice-korean ko' : '', children: choice.label }),
                },
                choice.id
              )
            }),
          },
          'choices'
        ),
      ]

  return f.jsxs(f.Fragment, {
    children: [
      f.jsxs(
        'div',
        {
          className: 'session-top',
          children: [
            f.jsx(
              'button',
              { className: 'btn ghost small', style: { width: 'auto' }, onClick: props.onExit, children: 'Exit' },
              'exit'
            ),
            f.jsx(
              'div',
              {
                className: 'progress-track',
                children: f.jsx('div', {
                  className: 'progress-fill',
                  style: { width: (session.position / Math.max(1, session.total)) * 100 + '%' },
                }),
              },
              'track'
            ),
            f.jsxs('span', { className: 'session-count', children: [session.position, '/', session.total] }, 'count'),
          ],
        },
        'top'
      ),
      f.jsx('div', { className: 'stage', children: stage }, 'stage'),
      ...answers,
      outcome === null
        ? null
        : f.jsxs(
            'div',
            {
              className: 'feedback ' + (outcome.correct ? 'good' : 'bad'),
              children: [
                f.jsx('p', { className: 'feedback-title', children: outcome.correct ? 'Correct' : 'Not quite' }, 'title'),
                f.jsxs(
                  'div',
                  {
                    className: 'feedback-card',
                    onClick: () => oreumSpeakSentence(engine, exercise.korean),
                    children: [
                      f.jsx('span', { className: 'sentence-korean ko', children: exercise.korean }, 'ko'),
                      f.jsx('span', { className: 'feedback-english', children: exercise.english }, 'en'),
                    ],
                  },
                  'card'
                ),
                f.jsx('p', { className: 'feedback-note', children: exercise.explanation }, 'note'),
                outcome.willRepeat
                  ? f.jsx(
                      'p',
                      { className: 'feedback-note', style: { opacity: 0.75 }, children: 'This one comes back before the end.' },
                      'repeat'
                    )
                  : null,
                f.jsx('button', { className: 'btn primary', onClick: props.onDone, children: 'Continue' }, 'continue'),
              ],
            },
            'feedback'
          ),
    ],
  })
}
